DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:GTC 057", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "0f3119d5-a523-53ec-98e0-849516773920", "stem": "A rectangle’s length decreases by 10% while its area stays constant. Approximately what percentage must its width increase, rounded to the nearest whole percent?", "choices": [{"key": "A", "text": "11%"}, {"key": "B", "text": "1.11%"}, {"key": "C", "text": "−11%"}, {"key": "D", "text": "None of these"}], "type": "mcq", "correct": "A", "explanation": "The new length is 0.9L. Constant area requires new width W/0.9=(10/9)W, an increase of (1/9)W, or 11.111...%. This rounds to 11%.", "topic": "Coordinate Geometry & Circles", "note": "Added the required rounding instruction; without it 11% is not the exact percentage.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 401, "extra_sources": []}, {"id": "clean:GTC 058", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "7d9b9c2f-9bef-5b44-8e2c-e4710aa138bf", "stem": "Amr deposits $12,000 at a nominal annual interest rate of 2.5%, compounded semiannually. With no deposits or withdrawals, how much interest is earned after 6 years, rounded to the nearest dollar?", "choices": [{"key": "A", "text": "$1,289"}, {"key": "B", "text": "$1,876"}, {"key": "C", "text": "$1,999"}, {"key": "D", "text": "$1,929"}], "type": "mcq", "correct": "D", "explanation": "The half-year rate is 0.025/2 and there are 12 periods. Interest=12000[(1+0.025/2)^12−1]≈$1929.0542, which rounds to $1929.", "topic": "Statistics, Probability & Data Analysis", "note": "Clarified that 2.5% is the annual nominal rate; the source’s “twice per year” wording is ambiguous without it.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 402, "extra_sources": [], "parts": [{"label": "Q9", "question_id": "32402814-0c34-59c0-82fd-3727a4aa6fe3", "stem": "What shape is the solution region of y≥x+1, y≤x+2, y≥1, and y≤3?", "choices": [{"key": "A", "text": "Triangle"}, {"key": "B", "text": "Rectangle"}, {"key": "C", "text": "Parallelogram"}, {"key": "D", "text": "Rhombus"}], "type": "mcq", "correct": "C", "explanation": "The vertices are (−1,1),(0,1),(2,3),(1,3). Opposite sides are parallel. Adjacent sides have lengths 1 and 2√2 and are not perpendicular, so the figure is a parallelogram that is neither a rectangle nor a rhombus.", "topic": "Coordinate Geometry & Circles", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:GTC 061", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "1b73cea9-812f-5166-b047-53fde56c8da0", "stem": "Triangle MNO is isosceles and right-angled at N. If MO=10, what is NO?", "choices": [{"key": "A", "text": "5√2"}, {"key": "B", "text": "2√5"}, {"key": "C", "text": "12.5"}, {"key": "D", "text": "5.5"}], "type": "mcq", "correct": "A", "explanation": "Let each equal leg be s. By Pythagoras, 2s²=10², so s²=50 and s=5√2.", "topic": "Coordinate Geometry & Circles", "note": "Corrected adaptation: replaced the ambiguous source distractor 2√(12·5) with 2√5. If its dot is read as a decimal, the original B equals A. Removed the unused parameter MN=2√a. Both source copies (pages 404 and 413) were checked.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 404, "extra_sources": [], "parts": [{"label": "Q6", "question_id": "3ebb89f2-6bf2-5693-b69e-01e1ce604bdb", "stem": "Two sides of a triangle have lengths 5 and 10. What is the least possible integer length of the third side?", "choices": [{"key": "A", "text": "6"}, {"key": "B", "text": "8"}, {"key": "C", "text": "7"}, {"key": "D", "text": "9"}], "type": "mcq", "correct": "A", "explanation": "The triangle inequality requires |10−5|<s<10+5, or 5<s<15. The smallest integer in this interval is 6.", "topic": "Coordinate Geometry & Circles", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:GTC 062", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Original Q10 is already represented by GTC 071: cos H=GH/BH=0.5, BH=10, so GH=5, C. Original Q11 is already HOA 220: subtracting equations gives 4x=17, so x=17/4, A. Both complete source questions visually verified; no duplicate questions created.", "correct": "C", "duplicate_of": "clean:GTC 071", "question_id": "7f1fa1bf-1d47-5439-b883-62e7e66cb8f3", "before": {"stem": "GTC 071 — Answer the original question below.", "choices": [{"key": "A", "text": "Option A in the original question"}, {"key": "B", "text": "Option B in the original question"}, {"key": "C", "text": "Option C in the original question"}, {"key": "D", "text": "Option D in the original question"}], "correct": "C", "explanation": "BH is the hypotenuse. cos(H)=GH/BH=0.5, hence GH=5."}}, {"id": "clean:GTC 063", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "8e8c1091-2814-556c-9fef-621ab9b118ec", "stem": "Two perpendicular lines have finite nonzero slopes m₁ and m₂. Which relation must hold?", "choices": [{"key": "A", "text": "m₁m₂=−1"}, {"key": "B", "text": "m₁−m₂=−1"}, {"key": "C", "text": "m₁+m₂=−1"}, {"key": "D", "text": "m₁/m₂=−1"}], "type": "mcq", "correct": "A", "explanation": "For nonvertical perpendicular lines the slopes are negative reciprocals, m₂=−1/m₁. Thus m₁m₂=−1. The other relations do not hold for every perpendicular pair.", "topic": "Coordinate Geometry & Circles", "note": "Added the finite nonzero slope condition to exclude the horizontal/vertical case where one slope is undefined.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 406, "extra_sources": [], "parts": [{"label": "Q6", "question_id": "10efcc43-44f1-5da3-8692-918b5c0e15bb", "stem": "The table has points (x,y)=(0.5,1),(1,0.5),(1.5,1/3). Which proposed variation model fits all three points?", "choices": [{"key": "A", "text": "y varies directly with x, k=0.5"}, {"key": "B", "text": "y varies directly with x, k=2"}, {"key": "C", "text": "y varies inversely with x, k=2"}, {"key": "D", "text": "y varies inversely with x, k=0.5"}], "type": "mcq", "correct": "D", "explanation": "The products xy are 0.5, 0.5, and 0.5. Thus each point satisfies y=0.5/x, the inverse-variation model with constant 0.5. Their ratios y/x are not constant.", "topic": "Functions, Transformations & Graphs", "note": "Transcribed all table values; asked which listed model fits, without claiming three points uniquely define an unrestricted function."}]}, {"id": "clean:GTC 064", "old_status": "ocr_screened_not_verified", "status": "needs_source_reconstruction", "note": "Both questions are defective in the original page. Q28 gives right-triangle legs AB=12.2 and BC=6 but altitude foot AD=9; these conflict, because the legs require AC≈13.596 and AD=AB²/AC≈10.947, not 9. Q29 literally reads 6≤2x−1≤5, which is impossible, and its four number-line choices are indistinguishable. No intended numerical/letter answer can be verified.", "correct": null}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
